ALTER TABLE public.profiles ADD COLUMN age_band text NOT NULL DEFAULT '18+';
CREATE OR REPLACE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE age text; typ text; BEGIN age=NEW.raw_user_meta_data->>'age_band'; typ=coalesce(NEW.raw_user_meta_data->>'account_type','adult_student'); IF age IS NULL OR age NOT IN ('14–17','18+') THEN RAISE EXCEPTION 'Debes tener al menos 14 años para registrarte. Tu familiar puede crear un perfil sin correo.'; END IF; IF typ IN ('family','teacher') AND age<>'18+' THEN RAISE EXCEPTION 'La cuenta familiar o docente requiere una persona adulta.'; END IF; IF typ NOT IN ('family','teacher','adult_student') THEN RAISE EXCEPTION 'Tipo de cuenta no válido'; END IF; INSERT INTO public.profiles(id,display_name,account_type,age_band) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name',''),typ,age); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE FUNCTION public.guard_profile_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.age_band<>OLD.age_band OR NEW.account_type<>OLD.account_type THEN RAISE EXCEPTION 'Los datos de autorización de la cuenta no son editables'; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.guard_profile_identity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_profile_identity BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_identity();
CREATE FUNCTION public.guard_learner_owner_age() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.age_band IN ('6–8','9–12','12–13') AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=NEW.owner_user_id AND p.age_band='18+' AND p.account_type='family') THEN RAISE EXCEPTION 'Los perfiles infantiles deben ser creados por un adulto familiar o tutor'; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.guard_learner_owner_age() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_child_learner BEFORE INSERT OR UPDATE ON public.learners FOR EACH ROW EXECUTE FUNCTION public.guard_learner_owner_age();